#!/usr/bin/env python3
"""Reproduce the public length chart; generator/research source is never served."""

import argparse
import json
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from aliquot.orbit_lengths import build_orbit_lengths  # noqa: E402

OUTPUT = ROOT / "site/length-data.js"


def render(data):
    lines = ["'use strict';",
             "// Generated by python3 scripts/build_orbit_lengths.py; do not edit.",
             "const AliquotLengthData = {"]
    entries = list(data.items())
    for i, (key, value) in enumerate(entries):
        suffix = "," if i < len(entries) - 1 else ""
        if isinstance(value, list):
            lines.append(f'  "{key}": [')
            lines.extend("    " + json.dumps(row, separators=(",", ":")) +
                         ("," if j < len(value) - 1 else "") for j, row in enumerate(value))
            lines.append("  ]" + suffix)
        else:
            lines.append(f'  "{key}": ' + json.dumps(value, separators=(",", ":")) + suffix)
    return "\n".join(lines + ["};", ""])


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="Check without modifying files.")
    args = parser.parse_args()
    expected = render(build_orbit_lengths())
    if args.check:
        if not OUTPUT.is_file() or OUTPUT.read_text() != expected:
            parser.exit(1, "Length data is stale: run python3 scripts/build_orbit_lengths.py\n")
    else:
        OUTPUT.write_text(expected)
        print("Updated site/length-data.js; refresh asset hashes next.")


if __name__ == "__main__":
    main()
